public class Span {
  private static final Path ROOT = Paths.get("/app/urnbay");

  private static void load(Map<String,String> idx, String rel) throws Exception {
    Path f = ROOT.resolve(rel);
    if (!Files.exists(f)) return;
    for (String line : Files.readAllLines(f)) {
      String t = line.trim();
      if (t.isEmpty()) continue;
      String[] fields = t.split("\\t");
      if (fields.length >= 2 && Files.isRegularFile(ROOT.resolve(fields[1])))
        idx.put(fields[0], fields[1]);
    }
  }

  private static void addParts(byte[] bytes, Gear gear,
                               Map<String,String> idx) throws Exception {
    Path hot = ROOT.resolve("hot");
    Files.createDirectories(hot);
    for (byte[] part : Slice.cut(bytes, gear.mask, gear.min, gear.max)) {
      String key = Seal.pay(part);
      String rel = idx.get(key);
      if (rel == null || !Files.isRegularFile(ROOT.resolve(rel))) {
        rel = "hot/" + key + ".blob";
        Path dst = ROOT.resolve(rel);
        if (!Files.exists(dst)) Files.write(dst, part);
        idx.put(key, rel);
      }
    }
  }

  private static byte[] reel(Path manifest, Map<String,String> idx) throws Exception {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    for (String line : Files.readAllLines(manifest)) {
      String key = line.trim();
      if (key.isEmpty()) continue;
      String rel = idx.get(key);
      if (rel == null || !Files.isRegularFile(ROOT.resolve(rel)))
        throw new IOException("missing silo piece " + key + " for " + manifest);
      out.write(Files.readAllBytes(ROOT.resolve(rel)));
    }
    return out.toByteArray();
  }

  public static void merge() throws Exception {
    Gear gear = Gear.load("/app/gearpit/live.gear");
    Map<String,String> idx = new LinkedHashMap<>();
    load(idx, "idx.tsv");
    load(idx, "keep/idx.tsv");
    load(idx, "hot/idx.tsv");
    load(idx, "cold/idx.tsv");

    // Also normalize unmarked silo payloads.  Snapshot the paths because
    // addParts extends idx while walking.
    for (String rel : new LinkedHashSet<>(idx.values()))
      addParts(Files.readAllBytes(ROOT.resolve(rel)), gear, idx);

    // Reconstruct whole reels before cutting: old piece edges must not become
    // artificial boundaries under the tightened gear.
    Path marks = ROOT.resolve("marks");
    if (Files.isDirectory(marks)) {
      try (DirectoryStream<Path> manifests = Files.newDirectoryStream(marks, "*.m")) {
        for (Path manifest : manifests) addParts(reel(manifest, idx), gear, idx);
      }
    }

    StringBuilder all = new StringBuilder();
    StringBuilder hot = new StringBuilder();
    for (Map.Entry<String,String> e : idx.entrySet()) {
      String line = e.getKey() + "\\t" + e.getValue() + "\\n";
      all.append(line);
      if (e.getValue().startsWith("hot/")) hot.append(line);
    }
    Files.writeString(ROOT.resolve("idx.tsv"), all.toString());
    Files.createDirectories(ROOT.resolve("hot"));
    Files.writeString(ROOT.resolve("hot/idx.tsv"), hot.toString());
    System.out.println("walked");
  }
}
